def shapes(g):
    seen=set()
    out={}
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] not in (0,) and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==g[y][x] and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                out[g[r][c]]=cells
    return out
