def rot(P): return {(q[1],-q[0]) for q in P}
def V(P): return {(r,-c) for r,c in P}
def H_(P): return {(c,r) for r,c in P}
for n_ in range(1,6):
    gi=G[f'Demo pair {n_} input']; go=G[f'Demo pair {n_} output']
    H,W=len(gi),len(gi[0])
    S={(r,c) for r in range(H) for c in range(W) if gi[r][c]==4}
    added={(r,c) for r in range(H) for c in range(W) if go[r][c]==4 and (r,c) not in S}
    r0=min(p[0] for p in S); c0=min(p[1] for p in S)
    base={(r-r0,c-c0) for r,c in S}
    imgs={frozenset(base)}
    changed=True
    while changed:
        changed=False
        for P in list(imgs):
            qrot=frozenset(rot(P))
            qv=frozenset(V(P))
            qh=frozenset(H_(P))
            imgs|= {qrot,qv,qh}
            if any(i!=P for i in {qrot,qv,qh}): changed=True
    sols=[]
    for Dd in imgs:
        if len(Dd)!=len(added): continue
        dr=min(p[0] for p in added)-min(p[0] for p in Dd)
        dc=min(p[1] for p in added)-min(p[1] for p in Dd)
        cc={(p[0]+dr,p[1]+dc) for p in Dd}
        if cc==added: sols.append(sorted(Dd)[:4],'offset',(dr,dc)); break
    print('demo',n_,'sols:',sols)

