import numpy as np
def components(g,color):
    H=len(g);W=len(g[0]);seen=np.zeros((H,W),bool);out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==color and not seen[i][j]:
                q=deque([(i,j)]);seen[i][j]=1;comp=[]
                while q:
                    a,b=q.popleft();comp.append((a,b))
                    for da,db in((-1,0),(1,0),(0,-1),(0,1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==color and not seen[x][y]:
                            seen[x][y]=1;q.append((x,y))
                out.append(comp)
    return out
